      location.hashCode ^
      description.hashCode ^
      cancelled.hashCode ^
      recurring.hashCode ^
      participants.hashCode ^
      invitationKey.hashCode ^
      myStatus.hashCode ^
      editable.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Event &&
